<?php
require dirname(__DIR__).'/includes/bootstrap.php';require_staff_or_admin();$errors=[];$editId=get_int('edit');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=post('action');$id=int_post('id');$name=post('name');if($a==='save'){if($name==='')$errors[]='กรุณากรอกชื่อประเภท';elseif((int)scalar('SELECT COUNT(*) FROM tbl_devices_type WHERE t_name=? AND t_id<>?',[$name,$id]))$errors[]='มีประเภทนี้แล้ว';else{try{if($id)execute_sql('UPDATE tbl_devices_type SET t_name=? WHERE t_id=?',[$name,$id]);else execute_sql('INSERT INTO tbl_devices_type(t_name) VALUES(?)',[$name]);flash('success',$id?'แก้ไขประเภทครุภัณฑ์เรียบร้อย':'เพิ่มประเภทครุภัณฑ์เรียบร้อย');redirect('staff/types.php');}catch(Throwable $e){$errors[]='บันทึกไม่สำเร็จ';}}}elseif($a==='delete'){if((int)scalar('SELECT COUNT(*) FROM tbl_devices WHERE ref_t_id=?',[$id])||(int)scalar('SELECT COUNT(*) FROM tbl_devices_service WHERE ref_t_id=?',[$id]))flash('danger','ลบไม่ได้ เนื่องจากประเภทนี้ถูกใช้งานอยู่');else{execute_sql('DELETE FROM tbl_devices_type WHERE t_id=?',[$id]);flash('success','ลบประเภทเรียบร้อย');}redirect('staff/types.php');}}
$rows=fetch_all('SELECT t.*,COUNT(d.no) total FROM tbl_devices_type t LEFT JOIN tbl_devices d ON d.ref_t_id=t.t_id GROUP BY t.t_id,t.t_name ORDER BY t.t_name');$edit=$editId?fetch_one('SELECT * FROM tbl_devices_type WHERE t_id=?',[$editId]):null;render_header('ประเภทครุภัณฑ์','types');
?>
<div class="page-intro"><div><h2>ประเภทครุภัณฑ์</h2><p>จัดกลุ่มอุปกรณ์เพื่อค้นหาและออกรายงานได้ง่าย</p></div></div><?php if($errors):?><div class="inline-alert danger"><b>!</b><span><?=implode('<br>',array_map('e',$errors))?></span></div><?php endif;?><div class="grid grid-3"><div class="card span-2"><div class="table-wrap"><table class="data-table"><thead><tr><th>ประเภท</th><th>จำนวนครุภัณฑ์</th><th>จัดการ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['t_name'])?></b></td><td><?=e($r['total'])?> รายการ</td><td><div class="btn-group"><a class="btn btn-soft btn-sm" href="?edit=<?=e($r['t_id'])?>">แก้ไข</a><form method="post" data-confirm="ลบประเภทนี้หรือไม่?"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['t_id'])?>"><button class="btn btn-danger-soft btn-sm">ลบ</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div><div class="card"><div class="card-header"><div><h3><?=$edit?'แก้ไขประเภท':'เพิ่มประเภท'?></h3></div></div><div class="card-body"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit['t_id']??0)?>"><div class="form-group"><label>ชื่อประเภท <span class="required">*</span></label><input class="form-control" name="name" maxlength="80" required value="<?=e($_POST['name']??($edit['t_name']??''))?>"></div><div class="form-actions mt-2"><?php if($edit):?><a class="btn btn-soft" href="<?=e(url('staff/types.php'))?>">ยกเลิก</a><?php endif;?><button class="btn btn-primary">บันทึก</button></div></form></div></div></div><?php render_footer();?>
